def compute(vars):
    may_gross_profit = vars["v1"]
    august_gross_profit = vars["v2"]
    change = august_gross_profit - may_gross_profit

    return {
        "value": change,
        "trace": {
            "may_gross_profit": may_gross_profit,
            "august_gross_profit": august_gross_profit,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
